{"cards": [{"node_code": "N_e9e5b9224d670114", "definition": "指驾驶员在驾驶过程中必须遵守的法律法规、道路通行规则、交通信号标志含义及驾驶行为规范，旨在保障道路通行秩序与安全。", "boundary": "本节点聚焦于“规则”本身及其在驾驶中的执行。边界在于区分“交通规则”与“驾驶技术”（技术侧重操作技巧，规则侧重合规性）及“交通工程”（工程侧重信号系统设计与道路规划）。若内容涉及交通法规的立法原理或司法判例，需视具体语境，若仅涉及驾驶员需知晓的通行规则，归本节点。", "includes": ["道路通行权、让行规则及交通信号标志解读", "驾驶员法定义务、禁止行为及违规处罚标准", "特殊路况（如学校区、施工区）的通行规定"], "excludes": ["交通信号控制系统的硬件设计与算法", "交通法律法规的立法程序与司法审判案例"], "sibling_distinctions": [{"other_code": "N_07f64a1924d4af89", "rule": "交通规则侧重“必须做什么/不能做什么”的合规性；先进驾驶经验侧重“如何更安全/高效地做”的技巧与策略。"}, {"other_code": "N_783f261a718c074d", "rule": "交通规则关注外部环境与法律约束；汽车一般保养与驾驶关注车辆状态维护及基础操作。"}], "cross_boundary_rule": "若内容涉及“因违反交通规则导致的事故责任认定”，主挂载交通规则；若涉及“事故后的车辆紧急处置”，主挂载汽车一般故障的检查与排除。"}, {"node_code": "N_783f261a718c074d", "definition": "涵盖驾驶员在日常驾驶前后及过程中对车辆进行的常规检查、清洁、润滑、调整等基础维护活动，以及保持车辆良好技术状态的基本驾驶操作要求。", "boundary": "本节点聚焦于“一般性”、“日常性”的保养与驾驶结合点。边界在于区分“一般保养”与“专业修理”（修理侧重故障修复与零部件更换，本节点侧重预防性维护与状态确认）。若内容涉及发动机大修或复杂电子系统诊断，归入汽车修理；若涉及出车前检查、日常清洁、简单调整，归本节点。", "includes": ["出车前、行车中、收车后的车辆例行检查（如油液、轮胎、灯光）", "车辆日常清洁、简单润滑及易损件（如雨刮、灯泡）的更换", "保持车辆良好技术状态的基础驾驶操作规范"], "excludes": ["发动机、变速箱等核心总成的拆解与专业维修", "车辆故障诊断仪的使用及复杂电子系统编程"], "sibling_distinctions": [{"other_code": "N_bf5605cf5e3a88df", "rule": "本节点侧重“预防”和“常规维护”，即在无故障或轻微异常时的保养；故障检查与排除侧重“诊断”和“修复”，即在出现异常或故障时的处理。"}, {"other_code": "N_e9e5b9224d670114", "rule": "本节点关注车辆物理状态维护；交通规则关注法律与通行规范。"}], "cross_boundary_rule": "若内容涉及“日常保养不当导致的故障预防”，主挂载本节点；若涉及“故障发生后的具体排除步骤”，主挂载汽车一般故障的检查与排除。"}, {"node_code": "N_bf5605cf5e3a88df", "definition": "研究驾驶员在行车过程中或停车状态下，对车辆出现的常见、轻微故障进行初步判断、检查及简单排除的技术与方法，旨在保障行车安全与连续性。", "boundary": "本节点聚焦于“一般故障”及“驾驶员可执行”的检查与排除。边界在于区分“一般故障排除”与“专业维修”（专业维修需专用工具、设备或深度拆解，本节点侧重驾驶员具备的基本技能）。若内容涉及更换轮胎、检查冷却液泄漏、简单电路断路排查，归本节点；若涉及发动机内部机械故障诊断，归入汽车修理。", "includes": ["常见故障（如爆胎、水温过高、灯光失效）的初步判断与应急处理", "驾驶员可执行的简单故障检查方法与工具使用", "故障排除后的基本验证与后续处理建议"], "excludes": ["需要专业举升设备、诊断电脑或深度拆解的复杂故障维修", "车辆零部件的制造原理与材料科学分析"], "sibling_distinctions": [{"other_code": "N_783f261a718c074d", "rule": "本节点侧重“故障发生后的响应与排除”；汽车一般保养与驾驶侧重“无故障时的预防性维护”。"}, {"other_code": "N_07f64a1924d4af89", "rule": "本节点侧重车辆技术状态的故障处理；先进驾驶经验侧重驾驶行为与策略。"}], "cross_boundary_rule": "若内容涉及“故障排除后的驾驶注意事项”，主挂载本节点；若涉及“因驾驶操作不当导致的故障预防”，主挂载汽车一般保养与驾驶或先进驾驶经验。"}]}
